package vn.svframe.svframelib.api.crafting.uimanager;
import vn.svframe.svframelib.api.crafting.uifilters.*; import vn.svframe.svframelib.api.util.ui.*; import java.util.*; import java.util.concurrent.ConcurrentHashMap;
public class UIFilterManager { private static final Map<String,UIFilter> FILTERS=new ConcurrentHashMap<>(); static{registerUIFilter(new VanillaUIFilter());registerUIFilter(new MythicItemUIFilter());} public static void registerUIFilter(UIFilter f){FILTERS.put(f.getIdentifier().toLowerCase(Locale.ROOT),f);} public static ProvidedUIFilter getUIFilter(String s,FriendlyFeedbackProvider fb){if(s==null)return null;String[] p=s.split(":",3);UIFilter f=FILTERS.get(p[0].toLowerCase(Locale.ROOT));if(f==null&&p.length>=2){f=FILTERS.get("vanilla");return new ProvidedUIFilter(f,p[0]+":"+p[1],p.length>2?p[2]:"");}return f==null?null:new ProvidedUIFilter(f,p.length>1?p[1]:"",p.length>2?p[2]:"");} public static ProvidedUIFilter getUIFilter(String source,String filter,String arg,String data,FriendlyFeedbackProvider fb){UIFilter f=FILTERS.get(filter.toLowerCase(Locale.ROOT));return f==null?null:new ProvidedUIFilter(f,arg,data);} }
